import { tags } from "typia";

/**
 * Single rating bucket within a review rating distribution.
 *
 * Represents the statistics for one discrete rating score, such as all reviews
 * that gave 5 stars. Buckets are typically rendered as bars in a histogram or
 * distribution chart.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IShoppingMallReviewRatingDistributionBucket = {
  /**
   * The discrete rating score represented by this bucket.
   *
   * For a standard 5-star system this will be an integer between scaleMin and
   * scaleMax (for example, 1, 2, 3, 4, or 5).
   */
  ratingValue: number & tags.Minimum<0>;

  /**
   * Number of reviews that fall into this rating bucket after all filters are
   * applied.
   *
   * The sum of reviewCount across all buckets will equal the totalReviewCount
   * reported in the parent distribution DTO.
   */
  reviewCount: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Percentage of reviews that fall into this rating bucket relative to the
   * totalReviewCount.
   *
   * Expressed as a value between 0 and 100, where 100 represents all reviews
   * in the current filter. This value can be used directly for charting
   * without recomputing client-side percentages.
   */
  percentage: number & tags.Minimum<0> & tags.Maximum<100>;
};
